import{_ as l,C as c,o as a,c as h,a0 as r,b as o,w as t,a as i,E as s,a1 as d}from"./chunks/framework.CzVS_xMp.js";const p="/ai-data-center-systems/assets/gpu-diagram.r15qIYJA.png",m="/ai-data-center-systems/assets/blackwell-sm.BwFICcuc.png",u="/ai-data-center-systems/assets/superpod-diagram.BYVCvpVX.png",C=JSON.parse('{"title":"How to Think About GPUs","description":"","frontmatter":{},"headers":[],"relativePath":"inference/efficient-llm-inference-systems/appendix/hardware-architectures/gpus.ko.md","filePath":"inference/efficient-llm-inference-systems/appendix/hardware-architectures/gpus.ko.md","lastUpdated":1788432796000}'),f={name:"inference/efficient-llm-inference-systems/appendix/hardware-architectures/gpus.ko.md"};function g(b,e,y,k,w,P){const n=c("Mermaid");return a(),h("div",null,[e[2]||(e[2]=r('<h1 id="how-to-think-about-gpus" tabindex="-1">How to Think About GPUs <a class="header-anchor" href="#how-to-think-about-gpus" aria-label="Permalink to &quot;How to Think About GPUs&quot;">​</a></h1><blockquote><p>Source: <a href="https://jax-ml.github.io/scaling-book/gpus/" target="_blank" rel="noreferrer">How to Think About GPUs</a>, part of <em>How To Scale Your Model</em>, published 2025-08-18.</p><p>This is an English lecture-note adaptation, not a line-by-line full translation. The goal is to translate the GPU mental model and connect it to LLM inference, quantization, and distributed serving notes in this repository.</p><p>Figures from the JAX Scaling Book are reused under the repository&#39;s <a href="./assets/jax-scaling-book/LICENSE">MIT License</a>.</p></blockquote><h2 id="reading-map" tabindex="-1">Reading Map <a class="header-anchor" href="#reading-map" aria-label="Permalink to &quot;Reading Map&quot;">​</a></h2><p>This article explains NVIDIA GPUs from the perspective of LLM scaling. The key is to not treat the GPU as one big computer.</p><blockquote><p>A GPU is a system in which many SMs, Tensor Cores, CUDA cores, registers, SMEM, L2, HBM, NVLink/NVSwitch, and InfiniBand are connected hierarchically.</p></blockquote><p>LLM performance depends on where in this hierarchy traffic gets stuck.</p><h2 id="_1-the-basic-unit-of-a-gpu-the-sm" tabindex="-1">1. The Basic Unit of a GPU: the SM <a class="header-anchor" href="#_1-the-basic-unit-of-a-gpu-the-sm" aria-label="Permalink to &quot;1. The Basic Unit of a GPU: the SM&quot;">​</a></h2><p>Modern ML GPUs such as H100/B200 contain many SMs (Streaming Multiprocessors). Each SM behaves like an independent small processor, and inside it there are Tensor Cores, CUDA cores, a register file, and shared memory.</p><p><img src="'+p+'" alt="Abstract GPU layout"></p><p>Source: <a href="https://jax-ml.github.io/scaling-book/gpus/" target="_blank" rel="noreferrer">JAX Scaling Book, &quot;How to Think About GPUs&quot;</a>, MIT License. The original caption describes this as an abstract layout of an H100/B200-style GPU with many SMs connected to HBM.</p><table tabindex="0"><thead><tr><th>Unit</th><th>Role</th></tr></thead><tbody><tr><td>Tensor Core</td><td>handles most of the matrix multiplication.</td></tr><tr><td>CUDA cores</td><td>handle elementwise ops, control-heavy ops, and reductions.</td></tr><tr><td>Warp scheduler</td><td>picks warps to execute and hides latency.</td></tr><tr><td>Register file</td><td>holds thread-local values.</td></tr><tr><td>SMEM/L1</td><td>keeps tiles, activations, and temporary data nearby.</td></tr></tbody></table><p>Since most LLM FLOPS are matmul, the Tensor Core is the most important. But overall performance is not determined by the Tensor Core alone. If you cannot feed tiles to the Tensor Core in time, peak FLOPS mean nothing.</p><p><img src="'+m+`" alt="H100 SM diagram"></p><p>Source: <a href="https://jax-ml.github.io/scaling-book/gpus/" target="_blank" rel="noreferrer">JAX Scaling Book, &quot;How to Think About GPUs&quot;</a>, MIT License. The original figure cites a Wccftech H100 SM diagram and explains SM subpartitions, Tensor Cores, warp schedulers, register files, CUDA cores, and L1 data cache.</p><h2 id="_2-tensor-cores-and-low-precision" tabindex="-1">2. Tensor Cores and Low Precision <a class="header-anchor" href="#_2-tensor-cores-and-low-precision" aria-label="Permalink to &quot;2. Tensor Cores and Low Precision&quot;">​</a></h2><p>With each GPU generation, Tensor Cores handle larger tiles and lower precision.</p><table tabindex="0"><thead><tr><th>Generation intuition</th><th>Important change</th></tr></thead><tbody><tr><td>Volta/Turing</td><td>Tensor Cores arrive in earnest</td></tr><tr><td>Ampere</td><td>TF32/BF16/FP16 paths expand</td></tr><tr><td>Hopper</td><td>FP8, TMA, warpgroup-level programming</td></tr><tr><td>Blackwell</td><td>FP4/NVFP4, larger Tensor Cores, TMEM</td></tr></tbody></table><p>Lower precision changes performance in two ways.</p><ol><li>It reads more elements over the same memory bandwidth.</li><li>It processes more multiply-accumulate per unit of silicon area.</li></ol><p>Connecting to Week 4&#39;s message:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Prefill:</span></span>
<span class="line"><span>  large GEMM -&gt; Tensor Core throughput matters -&gt; FP8/FP4 path matters</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Decode:</span></span>
<span class="line"><span>  small GEMV-like work -&gt; HBM bytes matter -&gt; reducing W4/W8 weight traffic matters</span></span></code></pre></div><h3 id="_2-1-from-a100-to-b300-what-changed" tabindex="-1">2.1 From A100 to B300: What Changed <a class="header-anchor" href="#_2-1-from-a100-to-b300-what-changed" aria-label="Permalink to &quot;2.1 From A100 to B300: What Changed&quot;">​</a></h3><p>The history of NVIDIA GPU generations is not simply a story of FLOPS going up. From the LLM perspective, memory capacity, HBM bandwidth, low-precision formats, and the scale-up interconnect all changed together.</p><table tabindex="0"><thead><tr><th>Generation</th><th>Public memory signal</th><th>Low-precision / compute signal</th><th>Interconnect signal</th><th>Inference implication</th></tr></thead><tbody><tr><td>A100</td><td>80GB HBM2e, over 2TB/s memory bandwidth</td><td>TF32, FP16/BF16, INT8/INT4 Tensor Core</td><td>NVLink generation used for 8-GPU nodes</td><td>70B-class serving usually needs sharding/quantization, and decode is sensitive to HBM traffic.</td></tr><tr><td>H100</td><td>HBM3, about 3TB/s class memory bandwidth</td><td>FP8 Transformer Engine, TMA, Hopper programming model</td><td>NVLink/NVSwitch, Quantum-2 InfiniBand ecosystem</td><td>The FP8 prefill/training path and faster collectives become important.</td></tr><tr><td>H200</td><td>141GB HBM3e, 4.8TB/s memory bandwidth</td><td>Hopper compute with larger/faster memory</td><td>Hopper NVLink/NVL system family</td><td>Even with the same Hopper compute, the larger KV cache and model fit favor inference.</td></tr><tr><td>B200 / DGX B200</td><td>DGX B200: 8 GPUs, 1,440GB total HBM3e, 64TB/s total HBM bandwidth</td><td>Blackwell FP4/FP8 Tensor Core path</td><td>5th-gen NVLink, 14.4TB/s aggregate NVLink bandwidth in DGX B200</td><td>The FP4/NVFP4 weight path and large memory bandwidth push decode cost/token down.</td></tr><tr><td>B300 / DGX B300</td><td>DGX B300 user guide: 8 x 288GB Blackwell Ultra GPUs</td><td>DGX B300: 144 PFLOPS FP4 inference class system number</td><td>5th-gen NVLink, 14.4TB/s aggregate NVLink bandwidth in DGX B300</td><td>A larger per-node memory envelope widens headroom for long-context, MoE, and high-concurrency inference.</td></tr></tbody></table><p>This table is a way of reading, not a procurement table. From A100 to H200, &quot;the ability to put more model/KV state on one GPU&quot; improved dramatically, and in the Blackwell generation FP4 and the rack-scale NVLink domain become the center of inference economics. Even at the same parameter count, the number of GPUs needed changes with context length, batch size, KV cache format, and quantization format.</p><h2 id="_3-simt-and-warp-divergence" tabindex="-1">3. SIMT and Warp Divergence <a class="header-anchor" href="#_3-simt-and-warp-divergence" aria-label="Permalink to &quot;3. SIMT and Warp Divergence&quot;">​</a></h2><p>GPUs use the SIMT (Single Instruction, Multiple Threads) model. Efficiency is high when the threads in the same warp execute the same instruction. When a branch condition splits, warp divergence occurs and some lanes sit idle.</p><p>Dense matmul in LLMs is very regular and fits GPUs well. The following workloads need more care.</p><table tabindex="0"><thead><tr><th>Workload</th><th>Risk</th></tr></thead><tbody><tr><td>token sampling</td><td>branching, small kernels, CPU/GPU sync</td></tr><tr><td>MoE routing</td><td>irregular dispatch, AllToAll, load imbalance</td></tr><tr><td>sparse attention</td><td>irregular memory access</td></tr><tr><td>small batch decode</td><td>low occupancy, launch overhead</td></tr></tbody></table><p>So a serving system must not only make one kernel fast; it must align batching, scheduling, routing, and fusion together.</p><h2 id="_4-the-gpu-memory-hierarchy" tabindex="-1">4. The GPU Memory Hierarchy <a class="header-anchor" href="#_4-the-gpu-memory-hierarchy" aria-label="Permalink to &quot;4. The GPU Memory Hierarchy&quot;">​</a></h2><p>The GPU memory hierarchy is the performance language of LLM inference.</p><table tabindex="0"><thead><tr><th>Level</th><th>Scope</th><th>Practical meaning</th></tr></thead><tbody><tr><td>Registers</td><td>thread/subpartition</td><td>fastest but very small.</td></tr><tr><td>SMEM/L1</td><td>SM-local</td><td>holds tiles and temporary buffers.</td></tr><tr><td>TMEM</td><td>Blackwell Tensor Core feeding</td><td>a new space for feeding the larger Tensor Core.</td></tr><tr><td>L2</td><td>GPU-wide shared cache</td><td>the last on-chip cache shared among SMs.</td></tr><tr><td>HBM</td><td>device memory</td><td>the main store for weights, activations, and KV cache.</td></tr><tr><td>NVLink/NVSwitch</td><td>GPU-GPU</td><td>important for tensor parallelism and collectives.</td></tr><tr><td>PCIe/InfiniBand</td><td>host/node/rack</td><td>important for scale-out and the storage/host path.</td></tr></tbody></table><p>As emphasized in Week 2, optimization is the work of pulling traffic from slow levels of the hierarchy to fast ones.</p>`,34)),(a(),o(d,null,{default:t(()=>[s(n,{id:"mermaid-452",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20A%5BHBM%5D%20--%3E%20B%5BL2%5D%0A%20%20%20%20B%20--%3E%20C%5BSMEM%20%2F%20L1%5D%0A%20%20%20%20C%20--%3E%20D%5BRegisters%20%2F%20TMEM%5D%0A%20%20%20%20D%20--%3E%20E%5BTensor%20Core%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20A%20accent%0A%20%20%20%20class%20B%2CC%20secondary%0A%20%20%20%20class%20D%20note%0A%20%20%20%20class%20E%20primary%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r(`<h3 id="_4-1-model-fit-kv-cache-can-hit-its-limit-before-weights" tabindex="-1">4.1 Model fit: KV cache can hit its limit before weights <a class="header-anchor" href="#_4-1-model-fit-kv-cache-can-hit-its-limit-before-weights" aria-label="Permalink to &quot;4.1 Model fit: KV cache can hit its limit before weights&quot;">​</a></h3><p>The most common mistake when looking at GPU memory fit is calculating only the model weights. Weights are just the starting point; in production serving, KV cache, activation/workspace, fragmentation, and runtime reserve all go in together.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weight memory ~= parameters x bytes_per_parameter</span></span>
<span class="line"><span></span></span>
<span class="line"><span>KV cache memory ~= layers</span></span>
<span class="line"><span>                x sequence_length</span></span>
<span class="line"><span>                x kv_heads</span></span>
<span class="line"><span>                x head_dim</span></span>
<span class="line"><span>                x 2  # key and value</span></span>
<span class="line"><span>                x bytes_per_element</span></span>
<span class="line"><span>                x batch_or_concurrency</span></span></code></pre></div><p>For example, even if a 70B model barely fits in one GPU memory budget under weight-only quantization, adding long context and high concurrency makes the KV cache hit the limit first. The reason the large memory of H200 and Blackwell matters for inference is not only to load larger models, but to hold longer context and more concurrent requests for the same model.</p><table tabindex="0"><thead><tr><th>Fit question</th><th>Why it matters</th></tr></thead><tbody><tr><td>Do only the weights fit, or does the KV cache fit too?</td><td>&quot;loadable&quot; and &quot;serviceable&quot; are different things.</td></tr><tr><td>What is the target context length?</td><td>decode capacity is sensitive to KV bytes/token.</td></tr><tr><td>What is the batch/concurrency?</td><td>KV cache grows with the number of requests.</td></tr><tr><td>What is the quantization format?</td><td>Weight memory and compute path shrink, but the KV dtype may stay the same.</td></tr><tr><td>How much fragmentation and reserve do you plan for?</td><td>Even PagedAttention does not eliminate allocator overhead and block waste.</td></tr></tbody></table><h2 id="_5-why-gpus-have-many-sms" tabindex="-1">5. Why GPUs Have Many SMs <a class="header-anchor" href="#_5-why-gpus-have-many-sms" aria-label="Permalink to &quot;5. Why GPUs Have Many SMs&quot;">​</a></h2><p>GPUs execute hundreds of small tasks in parallel to hide latency. While a warp blocked on a memory load waits, other warps run.</p><p>This works well when the batch is large and there are enough tiles. Conversely, when the decode batch is small, the following problems appear.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Explanation</th></tr></thead><tbody><tr><td>GPU-Util is high but throughput is low</td><td>kernels keep running but do not make enough use of the Tensor Core/HBM.</td></tr><tr><td>batch=1 decode is slow</td><td>there is not enough work to hide launch overhead and memory latency.</td></tr><tr><td>a small model is inefficient on an H100</td><td>the problem size does not fill the GPU.</td></tr></tbody></table><p>This connects exactly to the Week 2 lab result. <code>nvidia-smi</code> GPU-Util only tells you &quot;is the GPU busy&quot;, not &quot;is it doing useful work close to peak&quot;.</p><h2 id="_6-gpu-networking-inside-and-outside-the-node" tabindex="-1">6. GPU Networking: Inside and Outside the Node <a class="header-anchor" href="#_6-gpu-networking-inside-and-outside-the-node" aria-label="Permalink to &quot;6. GPU Networking: Inside and Outside the Node&quot;">​</a></h2><p>GPU scale-out must be viewed in two layers.</p><table tabindex="0"><thead><tr><th>Scope</th><th>Fabric</th><th>Typical use</th></tr></thead><tbody><tr><td>Intra-node</td><td>NVLink / NVSwitch</td><td>tensor parallelism, fast AllReduce</td></tr><tr><td>Inter-node</td><td>InfiniBand / Ethernet RDMA</td><td>data parallelism, pipeline parallelism, expert parallelism</td></tr><tr><td>Rack-scale</td><td>NVSwitch fabric like NVL72</td><td>a larger scale-up island</td></tr></tbody></table><p>Tensor parallelism communicates frequently inside a layer, so it is best bound to the fast scale-up fabric. Pipeline parallelism only passes activations at layer boundaries, so it is relatively more suitable for scale-out. MoE expert parallelism has a lot of AllToAll and is strongly affected by the fabric and routing.</p><h3 id="_6-1-read-interconnect-terms-separately" tabindex="-1">6.1 Read Interconnect Terms Separately <a class="header-anchor" href="#_6-1-read-interconnect-terms-separately" aria-label="Permalink to &quot;6.1 Read Interconnect Terms Separately&quot;">​</a></h3><p>When reading GPU interconnect documentation, you must distinguish similar names.</p><table tabindex="0"><thead><tr><th>Term</th><th>Scope</th><th>Practical reading</th></tr></thead><tbody><tr><td>NV-HBI</td><td>die-to-die inside a Blackwell package</td><td>the internal link that makes a dual-die GPU look like one accelerator.</td></tr><tr><td>NVLink-C2C</td><td>CPU-GPU chip-to-chip</td><td>close to the CPU-GPU coherent connection in Grace Hopper/Blackwell.</td></tr><tr><td>NVLink</td><td>GPU-GPU link</td><td>important for tensor parallel collectives, P2P, and fast scale-up traffic.</td></tr><tr><td>NVSwitch</td><td>switch fabric among many GPUs</td><td>builds an 8-GPU node or a larger scale-up island like NVL72.</td></tr><tr><td>PCIe</td><td>host/device/NIC standard I/O</td><td>the practical limit of the CPU path, NIC, storage, fallback, and non-NVLink P2P.</td></tr><tr><td>InfiniBand / RoCE</td><td>node/rack/cluster network</td><td>carries scale-out training/serving, DP/PP/EP traffic.</td></tr></tbody></table><p>Mixing up this hierarchy breaks performance estimates. Whether a tensor parallel AllReduce stays inside the NVLink domain or crosses rack-out RDMA changes latency and throughput a lot even with the same number of GPUs.</p>`,18)),(a(),o(d,null,{default:t(()=>[s(n,{id:"mermaid-718",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20A%5BOne%20GPU%3Cbr%2F%3ESM%20%2F%20HBM%20%2F%20L2%5D%20--%3E%20B%5BPackage%20%2F%20board%3Cbr%2F%3ENV-HBI%20%2F%20C2C%5D%0A%20%20%20%20B%20--%3E%20C%5BNode%20scale-up%3Cbr%2F%3ENVLink%20%2F%20NVSwitch%5D%0A%20%20%20%20C%20--%3E%20D%5BRack%20scale-up%20island%3Cbr%2F%3ENVL72%20class%20fabric%5D%0A%20%20%20%20D%20-.-%3E%20E%5BCluster%20scale-out%3Cbr%2F%3EInfiniBand%20%2F%20RoCE%5D%0A%0A%20%20%20%20A%20--%3E%20F%5Blocal%20tensor%20kernels%5D%0A%20%20%20%20C%20--%3E%20G%5Btensor%20parallel%20collectives%5D%0A%20%20%20%20D%20--%3E%20H%5Blarge%20model%20shard%3Cbr%2F%3Erack-local%20serving%5D%0A%20%20%20%20E%20--%3E%20I%5Bpipeline%20%2F%20expert%20%2F%20data%20parallel%3Cbr%2F%3Ecross-rack%20traffic%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20A%20primary%0A%20%20%20%20class%20B%2CC%2CD%20secondary%0A%20%20%20%20class%20E%20accent%0A%20%20%20%20class%20F%2CG%2CH%2CI%20note%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<p>A rack-scale design like Blackwell NVL72 is more accurately read as an attempt to widen a fast scale-up island to the rack level, rather than &quot;the scale-out network got faster&quot;. Still, the whole cluster does not become one NVLink domain; once you go outside the island, the scheduling, routing, and congestion problems of InfiniBand/RoCE reappear.</p><p><img src="'+u+`" alt="H100 SuperPod networking diagram"></p><p>Source: <a href="https://jax-ml.github.io/scaling-book/gpus/" target="_blank" rel="noreferrer">JAX Scaling Book, &quot;How to Think About GPUs&quot;</a>, MIT License. The original caption uses this as a typical H100 network: 8 GPUs form an NVLink domain through NVSwitches, and nodes are connected with switched InfiniBand.</p><h2 id="_7-looking-at-collectives-with-a-roofline" tabindex="-1">7. Looking at Collectives with a Roofline <a class="header-anchor" href="#_7-looking-at-collectives-with-a-roofline" aria-label="Permalink to &quot;7. Looking at Collectives with a Roofline&quot;">​</a></h2><p>For LLM scaling, the compute roofline alone is not enough. You need a communication roofline.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>compute time ~= FLOPs / GPU compute throughput</span></span>
<span class="line"><span>communication time ~= bytes / collective bandwidth</span></span></code></pre></div><p>For performance to scale well, compute time must be able to hide communication time. Otherwise, adding more GPUs does not increase speed.</p><table tabindex="0"><thead><tr><th>Parallelism</th><th>Communication pattern</th><th>Bottleneck lens</th></tr></thead><tbody><tr><td>Data parallelism</td><td>gradient AllReduce / ReduceScatter</td><td>batch tokens per GPU must be sufficient.</td></tr><tr><td>Tensor parallelism</td><td>activation AllReduce / AllGather</td><td>NVLink bandwidth and latency matter.</td></tr><tr><td>Pipeline parallelism</td><td>activation send/recv</td><td>bubble and stage balance matter.</td></tr><tr><td>Expert parallelism</td><td>token AllToAll</td><td>load balance and fabric routing matter.</td></tr></tbody></table><h2 id="_8-the-difference-between-gpus-and-tpus" tabindex="-1">8. The Difference Between GPUs and TPUs <a class="header-anchor" href="#_8-the-difference-between-gpus-and-tpus" aria-label="Permalink to &quot;8. The Difference Between GPUs and TPUs&quot;">​</a></h2><p>The original text explains the GPU by comparing it to the TPU. Both share the broad structure of &quot;matrix multiply unit + fast memory + network&quot;, but there are important differences.</p><table tabindex="0"><thead><tr><th>Dimension</th><th>GPU</th><th>TPU</th></tr></thead><tbody><tr><td>Compute granularity</td><td>many SMs executing in parallel</td><td>centered on a relatively large MXU</td></tr><tr><td>Flexibility</td><td>CUDA ecosystem and thread-level flexibility</td><td>compiler-managed regular execution</td></tr><tr><td>Memory</td><td>register/SMEM/L2/HBM/TMEM hierarchy</td><td>centered on VMEM/HBM</td></tr><tr><td>Network</td><td>NVLink/NVSwitch/IB ecosystem</td><td>ICI/DCN topology</td></tr><tr><td>Best fit</td><td>broad workloads, custom kernels, production serving</td><td>regular large matmul, JAX/XLA compiled workloads</td></tr></tbody></table><p>The GPU&#39;s strength is flexibility. Its weakness also comes from flexibility. Even the same computation can swing a lot in performance depending on kernel choice, layout, batch shape, and whether fusion is applied.</p><h2 id="_9-practical-tips-and-notes-from-the-inference-perspective" tabindex="-1">9. Practical Tips and Notes from the Inference Perspective <a class="header-anchor" href="#_9-practical-tips-and-notes-from-the-inference-perspective" aria-label="Permalink to &quot;9. Practical Tips and Notes from the Inference Perspective&quot;">​</a></h2><h3 id="prefill" tabindex="-1">Prefill <a class="header-anchor" href="#prefill" aria-label="Permalink to &quot;Prefill&quot;">​</a></h3><p>Prefill processes a long prompt in parallel. There are many large GEMMs and attention ops, and the Tensor Core can be filled well. Lower-precision compute paths like FP8/FP4 deliver direct benefit.</p><h3 id="decode" tabindex="-1">Decode <a class="header-anchor" href="#decode" aria-label="Permalink to &quot;Decode&quot;">​</a></h3><p>Decode generates tokens one at a time. If the batch is not large enough, GEMV and small attention kernels dominate. Then HBM bandwidth, KV cache layout, kernel launch overhead, and the batching scheduler matter.</p><h3 id="quantization" tabindex="-1">Quantization <a class="header-anchor" href="#quantization" aria-label="Permalink to &quot;Quantization&quot;">​</a></h3><p>Weight-only quantization is especially effective for decode. Weight+activation quantization or FP8 matters more in the prefill compute path. Which yields the bigger gain depends on the workload mix.</p><h3 id="distributed-serving" tabindex="-1">Distributed Serving <a class="header-anchor" href="#distributed-serving" aria-label="Permalink to &quot;Distributed Serving&quot;">​</a></h3><p>TP can be placed inside the fast scale-up fabric, and PP can be pushed to the slower scale-out fabric. MoE needs separate verification. Until you see what traffic pattern expert routing creates on the fabric, peak FLOPS cannot predict it.</p><h3 id="power-and-cooling-are-architecture-constraints" tabindex="-1">Power and cooling are architecture constraints <a class="header-anchor" href="#power-and-cooling-are-architecture-constraints" aria-label="Permalink to &quot;Power and cooling are architecture constraints&quot;">​</a></h3><p>In Blackwell-class systems, choosing a GPU is choosing power/cooling/topology. An 8-GPU system like DGX B200 lists up to about 14.3kW of system power on the NVIDIA product page. For servers in this class, you must look not only at &quot;how many FLOPS does the GPU have&quot; but also at the following.</p><table tabindex="0"><thead><tr><th>Question</th><th>Why it matters</th></tr></thead><tbody><tr><td>What is the rack power budget in kW?</td><td>Power feed and cooling hit the limit before the GPU count does.</td></tr><tr><td>Is air cooling possible, or is liquid cooling required?</td><td>Deployment lead time and facility requirements change.</td></tr><tr><td>What is tokens/sec/rack, not just tokens/sec/GPU?</td><td>Serving capacity must include rack power and network.</td></tr><tr><td>What rack layout is needed to widen the NVLink domain?</td><td>Cabling, switches, NICs, and serviceability are part of the topology.</td></tr><tr><td>How do p99 and throughput change under a power cap?</td><td>The perf/W optimum may differ from the max-TDP setting.</td></tr></tbody></table><h2 id="_10-repository-connections" tabindex="-1">10. Repository Connections <a class="header-anchor" href="#_10-repository-connections" aria-label="Permalink to &quot;10. Repository Connections&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repository topic</th><th>Connection</th></tr></thead><tbody><tr><td>Week 2 hardware foundations</td><td>directly connects to SM, Tensor Core, memory hierarchy, and GPU-Util interpretation.</td></tr><tr><td>Week 3 KV cache</td><td>explains HBM traffic and KV cache layout in the decode path.</td></tr><tr><td>Week 4 quantization</td><td>explains why FP8/FP4/W4A16 act differently on prefill/decode.</td></tr><tr><td>AI Systems Performance Engineering Chapter 4</td><td>connects to NCCL, NVLink, RDMA, and the collective roofline.</td></tr><tr><td>AI Systems Performance Engineering Chapter 3</td><td>connects how CPU pinning, NUMA locality, and the Topology Manager under Kubernetes affect GPU serving p99 and training step time.</td></tr><tr><td>NPU appendix</td><td>provides the basis for comparing the GPU scale-up fabric with the NPU compiler/runtime envelope.</td></tr></tbody></table><h2 id="_11-check-questions" tabindex="-1">11. Check Questions <a class="header-anchor" href="#_11-check-questions" aria-label="Permalink to &quot;11. Check Questions&quot;">​</a></h2><ol><li>How do the roles of Tensor Cores and CUDA cores differ on a GPU?</li><li>Why is a large GPU like an H100 inefficient when the decode batch is small?</li><li>Why can real throughput be low even when <code>nvidia-smi</code> GPU-Util is high?</li><li>Why is tensor parallelism usually grouped inside NVLink/NVSwitch?</li><li>Why does the benefit of quantization appear differently in prefill and decode?</li><li>Why are &quot;the model weights fit in GPU memory&quot; and &quot;production serving is possible&quot; different statements?</li><li>How should traffic that stays inside the NVLink/NVSwitch domain be evaluated differently from traffic that crosses InfiniBand/RoCE?</li><li>Why do power/cooling become architecture constraints in the Blackwell generation?</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Source</th></tr></thead><tbody><tr><td>JAX Scaling Book GPU chapter</td><td><a href="https://jax-ml.github.io/scaling-book/gpus/" target="_blank" rel="noreferrer">https://jax-ml.github.io/scaling-book/gpus/</a></td></tr><tr><td>NVIDIA A100 product page</td><td><a href="https://www.nvidia.com/en-us/data-center/a100/" target="_blank" rel="noreferrer">https://www.nvidia.com/en-us/data-center/a100/</a></td></tr><tr><td>NVIDIA H100 product page</td><td><a href="https://www.nvidia.com/en-us/data-center/h100/" target="_blank" rel="noreferrer">https://www.nvidia.com/en-us/data-center/h100/</a></td></tr><tr><td>NVIDIA H200 product page</td><td><a href="https://www.nvidia.com/en-us/data-center/h200/" target="_blank" rel="noreferrer">https://www.nvidia.com/en-us/data-center/h200/</a></td></tr><tr><td>NVIDIA DGX B200 product page</td><td><a href="https://www.nvidia.com/en-us/data-center/dgx-b200/" target="_blank" rel="noreferrer">https://www.nvidia.com/en-us/data-center/dgx-b200/</a></td></tr><tr><td>NVIDIA DGX B300 product page</td><td><a href="https://www.nvidia.com/en-us/data-center/dgx-b300/" target="_blank" rel="noreferrer">https://www.nvidia.com/en-us/data-center/dgx-b300/</a></td></tr><tr><td>NVIDIA DGX B300 user guide</td><td><a href="https://docs.nvidia.com/dgx/dgxb300-user-guide/introduction-to-dgxb300.html" target="_blank" rel="noreferrer">https://docs.nvidia.com/dgx/dgxb300-user-guide/introduction-to-dgxb300.html</a></td></tr><tr><td>NVIDIA Blackwell architecture</td><td><a href="https://www.nvidia.com/en-us/data-center/technologies/blackwell-architecture/" target="_blank" rel="noreferrer">https://www.nvidia.com/en-us/data-center/technologies/blackwell-architecture/</a></td></tr></tbody></table>`,30))])}const v=l(f,[["render",g]]);export{C as __pageData,v as default};
